def is_palindrome(s):
    # Your code here
    pass

solution:
def is_palindrome(s):
    s = s.lower().replace(' ', '')
    return s == s[::-1]

starter_code:
def factorial(n):
    # Your code here
    pass

solution:
def factorial(n):
    if n <= 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

